.card-product .card-title a {
  color: #212529;
  text-decoration: none;
  transition: color 75ms;
}
.card-product .card-title a:hover {
  color: #6f42c1;
}
.card-product.grid-item {
  position: relative;
}
.card-product.grid-item .card-body {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  border-radius: 0.5rem;
  background-image: linear-gradient(to bottom, rgba(0, 0, 0, 0), rgba(0, 0, 0, 0.5));
}
.card-product.grid-item .card-title,
.card-product.grid-item .card-title a {
  color: #fff;
}
.card-product.grid-item .card-title:hover,
.card-product.grid-item .card-title a:hover {
  color: #6f42c1;
}
.card-product.grid-item .card-subtitle {
  color: #e9ecef;
}
@media (max-width: 767.98px) {
  .card-product.carousel-product {
    display: flex;
    align-items: center;
    flex-direction: row;
  }
  .card-product.carousel-product > a {
    display: inline-block;
    flex: 0 0 25%;
    max-width: 25%;
  }
}

@media (min-width: 992px) {
  .carousel-control-prev, .carousel-control-next {
    bottom: 50%;
    top: unset;
    height: auto;
  }
}
@media (min-width: 992px) {
  .carousel-control-prev {
    left: unset;
    right: 100%;
  }
}
@media (min-width: 992px) {
  .carousel-control-next {
    right: unset;
    left: 100%;
  }
}

.dropdown-item i {
  width: 1.5rem;
  text-align: center;
  margin-right: 0.75rem;
  color: #adb5bd;
}

.pagination .page-link {
  border-radius: var(--bs-border-radius);
}

.steps {
  display: flex;
  flex-direction: column;
  border-width: 1px;
  border-color: var(--bs-border-color);
  border-style: solid;
  border-radius: var(--bs-border-radius);
  font-size: 1rem;
}
@media (min-width: 992px) {
  .steps {
    flex-direction: row;
    flex-wrap: wrap;
  }
}
.steps-item {
  display: flex;
  flex: 1;
  gap: 1.5rem;
  padding: 0.75rem 2rem 0.75rem 1.5rem;
  border-bottom: 4px solid transparent;
  position: relative;
  background-color: none;
  transition: border-color 0.15s ease-in-out;
}
.steps-item.completed {
  border-color: none;
  background: none;
}
.steps-item.completed .steps-icon {
  color: var(--bs-primary);
}
.steps-item.completed .steps-title {
  color: var(--bs-gray-dark);
}
.steps-item:hover {
  text-decoration: none;
  background: none;
  border-color: var(--bs-light);
}
.steps-item:hover .steps-icon {
  color: var(--bs-gray);
}
.steps-item:hover .steps-title {
  color: var(--bs-gray);
}
.steps-item.active {
  border-color: #6f42c1;
  background: none;
}
.steps-item.active .steps-icon {
  color: #6f42c1;
}
.steps-item.active .steps-title {
  color: #6f42c1;
}
.steps-item.disabled {
  cursor: auto;
  pointer-events: none;
  border-color: none;
  background: none;
}
.steps-item.disabled .steps-icon {
  color: var(--bs-gray);
}
.steps-item.disabled .steps-title {
  color: var(--bs-gray);
}
.steps-title {
  color: var(--bs-gray);
}
.steps-icon {
  font-size: 2rem;
  color: var(--bs-gray);
}
.steps-text {
  color: var(--bs-gray);
  font-size: 0.875rem;
  line-height: 1.5;
}
.steps-divider {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  width: 1rem;
  color: var(--bs-border-color);
}

.pre-footer {
  transform: translateY(-50%);
  margin-top: -3rem;
}
.pre-footer-col {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}
.pre-footer .fa-solid {
  width: 3rem;
  text-align: center;
  color: #A0EFD8;
}

